import{_ as e,c as r,o as h,af as i}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"19、【临】 兑下坤上","description":"横渠易说 - 19、【临】 兑下坤上","frontmatter":{"title":"19、【临】 兑下坤上","description":"横渠易说 - 19、【临】 兑下坤上"},"headers":[],"relativePath":"zh/classics/hengqu/021.md","filePath":"zh/classics/hengqu/021.md"}'),l={name:"zh/classics/hengqu/021.md"};function t(n,a,s,d,c,o){return h(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="_19、【临】-兑下坤上" tabindex="-1">19、【临】 兑下坤上 <a class="header-anchor" href="#_19、【临】-兑下坤上" aria-label="Permalink to “19、【临】 兑下坤上”">​</a></h1><h3 id="彖曰-临-刚浸而长-说而顺-刚中而应。大亨以正-天之道也。-至于八月有凶-消不久也。" tabindex="-1">彖曰：临，刚浸而长，说而顺，刚中而应。大亨以正，天之道也。“至于八月有凶”，消不久也。 <a class="header-anchor" href="#彖曰-临-刚浸而长-说而顺-刚中而应。大亨以正-天之道也。-至于八月有凶-消不久也。" aria-label="Permalink to “彖曰：临，刚浸而长，说而顺，刚中而应。大亨以正，天之道也。“至于八月有凶”，消不久也。”">​</a></h3><h3 id="象曰-泽上有地-临-君子以教思无穷-容保民无疆。" tabindex="-1">象曰：泽上有地，临，君子以教思无穷，容保民无疆。 <a class="header-anchor" href="#象曰-泽上有地-临-君子以教思无穷-容保民无疆。" aria-label="Permalink to “象曰：泽上有地，临，君子以教思无穷，容保民无疆。”">​</a></h3><p>临言“有凶”者，大抵易之于爻，变阳至二，便为之戒，恐有过满之萌。未过中已戒，犹履霜坚冰之义，及泰之三曰：“无平不陂，无往不复”，皆过中之戒也。</p><h3 id="初九-咸临-贞吉。-象曰-咸临贞吉-志行正也。" tabindex="-1">初九，咸临，贞吉。 象曰：“咸临贞吉”，志行正也。 <a class="header-anchor" href="#初九-咸临-贞吉。-象曰-咸临贞吉-志行正也。" aria-label="Permalink to “初九，咸临，贞吉。 象曰：“咸临贞吉”，志行正也。”">​</a></h3><p>临为刚长，己志应上，故虽感而行正也。</p><h3 id="九二-咸临-吉-无不利。-象曰-咸临吉无不利-未顺命也。" tabindex="-1">九二，咸临，吉，无不利。 象曰：“咸临吉无不利”，未顺命也。 <a class="header-anchor" href="#九二-咸临-吉-无不利。-象曰-咸临吉无不利-未顺命也。" aria-label="Permalink to “九二，咸临，吉，无不利。 象曰：“咸临吉无不利”，未顺命也。”">​</a></h3><p>非咸则有上下之疑，有所不利。</p><h3 id="六三-甘临-无攸利。既忧之-无咎。-象曰-甘临-位不当也。-既忧之-咎不长也。" tabindex="-1">六三，甘临，无攸利。既忧之，无咎。 象曰：“甘临”，位不当也。“既忧之”，咎不长也。 <a class="header-anchor" href="#六三-甘临-无攸利。既忧之-无咎。-象曰-甘临-位不当也。-既忧之-咎不长也。" aria-label="Permalink to “六三，甘临，无攸利。既忧之，无咎。 象曰：“甘临”，位不当也。“既忧之”，咎不长也。”">​</a></h3><p>体说乘刚故甘，邪说求容而以临物，安有所利!能自忧惧，庶可免咎。</p><h3 id="六四-至临-无咎。-象曰-至临无咎-位当也。" tabindex="-1">六四，至临，无咎。 象曰：“至临无咎”，位当也。 <a class="header-anchor" href="#六四-至临-无咎。-象曰-至临无咎-位当也。" aria-label="Permalink to “六四，至临，无咎。 象曰：“至临无咎”，位当也。”">​</a></h3><p>以阴居阴，体顺应正，尽临之道，虽在刚长，可以无咎。正一作说。</p><h3 id="六五-知临-大君之宜-吉。-象曰-大君之宜-行中之谓也。" tabindex="-1">六五，知临，大君之宜，吉。 象曰：“大君之宜”，行中之谓也。 <a class="header-anchor" href="#六五-知临-大君之宜-吉。-象曰-大君之宜-行中之谓也。" aria-label="Permalink to “六五，知临，大君之宜，吉。 象曰：“大君之宜”，行中之谓也。”">​</a></h3><p>顺命行中，天子之宜。</p><h3 id="上六-敦临-吉-无咎。-象曰-敦临之吉-志在内也。" tabindex="-1">上六，敦临，吉，无咎。 象曰：敦临之吉，志在内也。 <a class="header-anchor" href="#上六-敦临-吉-无咎。-象曰-敦临之吉-志在内也。" aria-label="Permalink to “上六，敦临，吉，无咎。 象曰：敦临之吉，志在内也。”">​</a></h3><p>体顺则无所违，极上则无所进，不以无应而志在于临，故曰敦临志在内也。</p>',16)])])}const b=e(l,[["render",t]]);export{_ as __pageData,b as default};
